function integrate(dbs):
    assert sheaf_condition(dbs)          # precondition
    merged := empty_database
    for db in dbs:
        merged := glue(merged, db)       # prefer existing, fall back to db
    return merged                        # extends every source faithfully

function glue(db1, db2):
    result := copy(db2)
    for (p, v) in db1: result[p] := v    # db1 wins on overlap
    return result

function coboundary_norm(dbs, nRows, nCols):
    total := 0
    for db1 in dbs:
        for db2 in dbs:
            for r in 0..nRows-1:
                for c in 0..nCols-1:
                    if (r,c) in dom(db1) and (r,c) in dom(db2)
                       and db1[(r,c)] != db2[(r,c)]:
                        total := total + 1
    return total      # 0  <=>  sheaf condition holds

